\begin{Lem}
  Let $G$ be an $r$-graph with  $n$ vertices. Its weight polynomial $w(G,\xv)$ could be rewritten as
  \begin{equation*}
    w(G,\xv) = \frac{1}{r}\At\xv^r,
  \end{equation*}
  where $\At\xv^r := \sum_{i_1=1}^n\cdots\sum_{i_r=1}^n a_{i_1\cdots i_r}x_{i_1}\cdots x_{i_r}$.
\end{Lem}

\begin{proof}
  By direct calculations, it yields that
  \begin{eqnarray}
  \frac{1}{r}\At\xv^r &=& \frac{1}{r}\sum_{i_1=1}^n\cdots\sum_{i_r=1}^n a_{i_1\cdots i_r}x_{i_1}\cdots x_{i_r} \nonumber\\
    &=& \frac{1}{r}\sum_{{\{i_1,\dots,i_r\}\in E}\atop i_1<\dots<i_r} \frac{1}{(r-1)!} r! x_{i_1}\cdots x_{i_r} \nonumber\\
    &=& \sum_{e\in E}\prod_{i\in e}x_i = w(G,\xv). \label{aaabbb}
  \end{eqnarray}
  The proof is completed.
\end{proof}

\begin{Lem}\label{Lem:4-2}
  There exists a constant $\kappa_1>0$ such that for any $\rho_c$ generated by Algorithm \ref{Alg:pGrad}
  \begin{equation*}
    \rho_c\ge \kappa_1.
  \end{equation*}

\end{Lem}

\begin{proof}
  We will prove that the inequality \eqref{LineSch} is valid
  %\begin{equation*}
  %  f(\xv_c+\rho\gv_c) \le f(\xv_c)+\eta\rho\gv_c^T \nabla f(\xv_c)
  %\end{equation*}
  when $\rho\in[0, \frac{2(1-\eta)}{\overline{\alpha}M}]$. By Lemma \ref{Lem:4-1}, it yields that $\|\gv_c\|^2\le\alpha_c\gv_c^T\nabla f(\xv_c)$. From Taylor's formula, we have
  \begin{eqnarray*}
    f(\xv_c+\rho\gv_c) &\ge& f(\xv_c)+\rho \gv_c^T\nabla f(\xv_c)-\frac{M}{2}\rho^2\|\gv_c\|^2 \\
      &\ge& f(\xv_c)+\rho \gv_c^T\nabla f(\xv_c) -\frac{M}{2}\rho^2\alpha_c\gv_c^T\nabla f(\xv_c) \\
      &\ge& f(\xv_c)+\rho \gv_c^T\nabla f(\xv_c) -(1-\eta)\rho\gv_c^T\nabla f(\xv_c) \\
      &=& f(\xv_c)+\eta\rho \gv_c^T\nabla f(\xv_c),
  \end{eqnarray*}
  where the last inequality holds owing to the assumption $0\le\rho\alpha_cM\le \rho\overline{\alpha}M\le 2(1-\eta)$. According to Step 4 of Algorithm GPA,  this lemma is valid if $\kappa_1:=\frac{2\beta(1-\eta)}{\overline{\alpha}M}$.
\end{proof}

\begin{Thm}\label{Thm:4-3}
  Suppose that $\{\xv_c\}$ is an infinity sequence of iterates generated by GPA. Then, we have
  \begin{equation*}
    \lim_{c\to\infty} \|\pi_{\Delta}(\xv_c + \nabla f(\xv_c))-\xv_c\| = 0.
  \end{equation*}
  That is to say, every limit point of $\{\xv_c\}$ is a critical point.
\end{Thm}

\begin{proof}
  From \eqref{LineSch}, Lemmas \ref{Lem:4-1} and \ref{Lem:4-2}, we obtain
  \begin{equation}\label{fun-lowbd}
    f(\xv_{c+1})-f(\xv_c) \ge \eta\rho_c\gv_c^T\nabla f(\xv_c) \ge \frac{\eta\rho_c}{\alpha_c}\|\gv_c\|^2
      \ge \frac{\eta\kappa_1}{\overline{\alpha}}\|\gv_c\|^2.
  \end{equation}
  Hence, we have
  \begin{equation*}
    \sum_{c=1}^{\infty} \|\gv_c\|^2 \le \frac{\overline{\alpha}}{\eta\kappa_1}\sum_{c=1}^{\infty}[f(\xv_{c+1})-f(\xv_c)]
       \le \frac{\overline{\alpha}}{\eta\kappa_1}\lambda(G),
  \end{equation*}
  which means that $\|\gv_c\| \to0$ as $c\to\infty$.

  On one hand, if $\alpha_c\ge1$, we get $\|\gv^{\alpha_c}(\xv_c)\|\ge\|\gv^1(\xv_c)\|$ by Lemma \ref{Lem:4-1}. On the other hand, $\alpha_c<1$ and hence $\|\gv^{\alpha_c}(\xv_c)\|/\alpha_c\ge\|\gv^1(\xv_c)\|$. Hence, we have
  \begin{equation}\label{gc-lowbd}
    \|\gv_c\|=\|\gv^{\alpha_c}(\xv_c)\|\ge \min\{\alpha_c,1\}\|\gv^1(\xv_c)\| \ge \min\{\underline{\alpha},1\}\|\gv^1(\xv_c)\|.
  \end{equation}
 Therefore $\|\gv^1(\xv_c)\|$ tends to zero. The proof is then completed.
\end{proof}

\begin{Thm}[{\L}ojasiewicz property]\label{Thm:5-1}
  Suppose that $\xv_*$ is a critical point of \eqref{OPM}, i.e., $\gv^1(\xv_*)=0$. Then, there exist a neighborhood of $\xv_*$ denoted as $\mathds{U}(\xv_*)$, an exponent $\theta\in[1/2,1)$, and a positive constant $C$ such that the following inequality
  \begin{equation*}
    \|\gv^1(\xv)\| \ge C|f(\xv)-f(\xv_*)|^{\theta}
  \end{equation*}
  holds for all $\xv\in \mathds{U}(\xv_*) \cap\Delta$.
\end{Thm}

\begin{Lem}\label{Lem:5-2}
  Let $\xv_*$ be a limiting point of $\{\xv_c\}$. The initial iterate $\xv_0$ is sufficiently close to $\xv_*$ in the sense that $\xv_0\in\mathds{B}(\xv_*,\sigma)\cap\Delta$, where $\mathds{B}(\xv_*,\sigma):=\{\xv\in\Re^n:\|\xv-\xv_*\|<\sigma\}\subseteq\mathds{U}(\xv_*)$ and $\sigma\ge \frac{\max\{1,\overline{\alpha}\}}{\eta C(1-\theta)}|f(\xv_0)-f(\xv_*)|^{1-\theta}+\|\xv_0-\xv_*\|$. Then, we have the following two assertions:
  \begin{equation*}
    \xv_c\in\mathds{B}(\xv_*,\sigma)\cap\Delta \qquad\text{ for }c=0,1,2,\dots,
  \end{equation*}
  and
  \begin{equation*}
    \sum_{c=0}^{\infty}\|\xv_c-\xv_{c+1}\| \le \frac{\max\{1,\overline{\alpha}\}}{\eta C(1-\theta)}|f(\xv_0)-f(\xv_*)|^{1-\theta}.
  \end{equation*}
\end{Lem}

\begin{proof}
The conclusions can be  proved by  induction. It is obvious to see that $\xv_0\in\mathds{B}(\xv_*,\sigma)\cap\Delta$. Next, by supposing that there exists a positive integer $\ell$ such that
  \begin{equation*}
    \xv_c\in\mathds{B}(\xv_*,\sigma)\cap\Delta \qquad\text{ for }c=0,1,\dots,\ell,
  \end{equation*}
  we show $\xv_{\ell+1}\in\mathds{B}(\xv_*,\sigma)\cap\Delta$.

  Define $\phi(t):=\frac{1}{C(1-\theta)}|t-f(\xv_*)|^{1-\theta}$. It is easy to see that $\phi(t)$ is a monotonically decreasing and  \cl{concave} function for  $t<f(\xv_*)$. Then, for $0\le c\le \ell$, we have
  \begin{eqnarray*}
    \phi(f(\xv_c))-\phi(f(\xv_{c+1}))
      &\ge& \phi'(f(\xv_c))(f(\xv_c)-f(\xv_{c+1})) \\
      &=& \frac{-1}{C|f(\xv_c)-f(\xv_*)|^{\theta}} (f(\xv_c)-f(\xv_{c+1})) \\
      &\ge& \frac{1}{\|\gv^1(\xv_c)\|}(f(\xv_{c+1})-f(\xv_c)) \\
      &\ge& \frac{1}{\|\gv^1(\xv_c)\|}\frac{\eta\rho_c}{\alpha_c}\|\gv_c\|^2 \\
      &\ge& \frac{1}{\|\gv^1(\xv_c)\|}\frac{\eta\rho_c}{\alpha_c}\|\gv_c\|\min\{\alpha_c,1\}\|\gv^1(\xv_c)\| \\
      &=& \frac{\eta\min\{\alpha_c,1\}}{\alpha_c}\|\rho_c\gv_c\| \\
      &=& \eta\min\{1,\alpha_c^{-1}\}\|\xv_c-\xv_{c+1}\|,
  \end{eqnarray*}
  where the second inequality is obtained based on Theorem \ref{Thm:5-1}, the third inequality is deduced from \eqref{fun-lowbd}, and the fourth inequality is valid because of \eqref{gc-lowbd}. The above inequalities indicate that
  \begin{equation*}
    \|\xv_c-\xv_{c+1}\| \le \frac{\max\{1,\overline{\alpha}\}}{\eta}\left(\phi(f(\xv_c))-\phi(f(\xv_{c+1}))\right),
  \end{equation*}
  for $0\le c\le \ell$. Hence, it holds that
  \begin{equation}\label{iterate-length}
    \sum_{c=0}^{\ell} \|\xv_c-\xv_{c+1}\|
      \le \frac{\max\{1,\overline{\alpha}\}}{\eta}\sum_{c=0}^{\ell}\left(\phi(f(\xv_c))-\phi(f(\xv_{c+1}))\right)
      \le \frac{\max\{1,\overline{\alpha}\}}{\eta}\phi(f(\xv_0)).
  \end{equation}
  Therefore, we have
  \begin{equation*}
    \|\xv_{\ell+1}-\xv_*\| \le \|\xv_0-\xv_*\|+\sum_{c=0}^{\ell} \|\xv_c-\xv_{c+1}\|
      \le \|\xv_0-\xv_*\|+\frac{\max\{1,\overline{\alpha}\}}{\eta}\phi(f(\xv_0)) <\sigma,
  \end{equation*}
  which implies that $\xv_{\ell+1}\in\mathds{B}(\xv_*,\sigma)$. On the other hand, every iterate is feasible by the mechanism of GPA.  Hence, we obtain the first assertion. The second  conclusion comes from \eqref{iterate-length} straightforwardly by setting $\ell\to\infty$.
\end{proof}

\begin{proof}
  Without loss of generality, we assume $\xv_0\in\mathds{B}(\xv_*,\sigma)$. Define
  \begin{equation*}
    \zeta_c:=\sum_{\ell=c}^{\infty} \|\xv_{\ell}-\xv_{\ell+1}\| \ge \|\xv_c-\xv_*\|.
  \end{equation*}
  From Lemma \ref{Lem:5-2} and Theorem \ref{Thm:5-1}, we have
  \begin{eqnarray*}
    \zeta_c &\le& \frac{\max\{1,\overline{\alpha}\}}{\eta C(1-\theta)}|f(\xv_c)-f(\xv_*)|^{1-\theta} \\
      &=& \frac{\max\{1,\overline{\alpha}\}}{\eta C^{1/\theta}(1-\theta)}\left(C|f(\xv_c)-f(\xv_*)|^{\theta}\right)^{(1-\theta)/\theta} \\
      &\le& \frac{\max\{1,\overline{\alpha}\}}{\eta C^{1/\theta}(1-\theta)}\left(\|\gv^1(\xv_c)\|\right)^{(1-\theta)/\theta}.
  \end{eqnarray*}
  It can be obtained from Lemma \ref{Lem:4-2} and \eqref{gc-lowbd} that
  \begin{equation*}
    \|\xv_c-\xv_{c+1}\| = \rho_c\|\gv_c\| \ge \kappa_1\min\{\underline{\alpha},1\}\|\gv^1(\xv_c)\|.
  \end{equation*}
  Hence, by denoting $\kappa_2:=\frac{\max\{1,\overline{\alpha}\}}{\eta C^{1/\theta}(1-\theta)}(\kappa_1\min\{\underline{\alpha},1\})^{-(1-\theta)/\theta}$, we get
  \begin{equation}\label{zeta-1}
    \zeta_c \le \kappa_2\|\xv_c-\xv_{c+1}\|^{(1-\theta)/\theta} = \kappa_2(\zeta_c-\zeta_{c+1})^{(1-\theta)/\theta}.
  \end{equation}
  If $\theta=1/2$, the inequality \eqref{zeta-1} means
  \begin{equation*}
    \zeta_{c+1} \le \frac{\kappa_2-1}{\kappa_2}\zeta_c.
  \end{equation*}
  Hence, the first estimation holds with $\gamma=\zeta_0$ and $\mu=(\kappa_2-1)/\kappa_2$.

  Next, we consider the case $\theta\in(1/2,1)$. Let $\varphi(t):=t^{-\theta/(1-\theta)}$ be a decreasing function for $t>0$. It yields from \eqref{zeta-1} that
  \begin{eqnarray*}
    \kappa_2^{-\theta/(1-\theta)} &\le& \varphi(\zeta_c)(\zeta_c-\zeta_{c+1}) \\
      &=& \int_{\zeta_{c+1}}^{\zeta_c} \varphi(\zeta_c) \mathrm{d}t \\
      &\le& \int_{\zeta_{c+1}}^{\zeta_c} \varphi(t) \mathrm{d}t \\
      &=& \cl{\frac{1-\theta}{1-2\theta}}\left(\zeta_{c+1}^{-(2\theta-1)/(1-\theta)}-\zeta_c^{-(2\theta-1)/(1-\theta)}\right),
  \end{eqnarray*}
  which implies
  \begin{equation*}
    \zeta_{c+1}^{-(2\theta-1)/(1-\theta)}-\zeta_c^{-(2\theta-1)/(1-\theta)}
      \ge \cl{\frac{1-2\theta}{1-\theta}}\kappa_2^{-\theta/(1-\theta)} := \kappa_3>0.
  \end{equation*}
Then, we have
  \begin{equation*}
    \zeta_c^{-(2\theta-1)/(1-\theta)} \ge \kappa_3+\zeta_{c-1}^{-(2\theta-1)/(1-\theta)} \ge\dots
      \ge \kappa_3c+\zeta_0^{-(2\theta-1)/(1-\theta)},
  \end{equation*}
  which means
  \begin{equation*}
    \zeta_c \le \left(\kappa_3c+\zeta_0^{-(2\theta-1)/(1-\theta)}\right)^{-(1-\theta)/(2\theta-1)}
      \le (\kappa_3c)^{-(1-\theta)/(2\theta-1)}.
  \end{equation*}
The last estimation holds by taking $\gamma_2=\kappa_3^{-(1-\theta)/(2\theta-1)}$.

   Let $\xi_c:=|f(\xv_c)-f(\xv_*)|$. From \eqref{fun-lowbd}, \eqref{gc-lowbd}, and Theorem \ref{Thm:5-1}, we have
  \begin{eqnarray*}
    \xi_c-\xi_{c+1} &=& f(\xv_{c+1})-f(\xv_c) \\
      &\ge& \frac{\eta\kappa_1}{\overline{\alpha}}\|\gv_c\|^2 \\
      &\ge& \frac{\eta\kappa_1(\min\{\underline{\alpha},1\})^2}{\overline{\alpha}}\|\gv^1(\xv_c)\|^2 \\
      &\ge& \frac{\eta\kappa_1C^2(\min\{\underline{\alpha},1\})^2}{\overline{\alpha}}\xi_c^{2\theta}
      := \kappa_4 \xi_c^{2\theta}.
  \end{eqnarray*}
Denote $\chi(t):=t^{-2\theta}$ as a decreasing function for $t>0$. It is deduced from the above inequality that
  \begin{equation*}
    \kappa_4 \le \chi(\xi_c)(\xi_c-\xi_{c+1})
      = \int_{\xi_{c+1}}^{\xi_c} \chi(\xi_c) \mathrm{d}t
      \le \int_{\xi_{c+1}}^{\xi_c} \chi(t) \mathrm{d}t
      = \frac{1}{2\theta-1}\left(\xi_{c+1}^{-(2\theta-1)}-\xi_c^{-(2\theta-1)}\right).
  \end{equation*}
  Let $\kappa_5:=(2\theta-1)\kappa_4>0$. We have
  \begin{equation*}
    \xi_c^{-(2\theta-1)} \ge \kappa_5+\xi_{c-1}^{-(2\theta-1)} \ge \dots \ge\kappa_5c+\xi_0^{-(2\theta-1)},
  \end{equation*}
  which means
  \begin{equation*}
    \xi_c \le \left(\kappa_5c+\xi_0^{-(2\theta-1)}\right)^{-1/(2\theta-1)}
      \le (\kappa_5c)^{-1/(2\theta-1)}.
  \end{equation*}
The second estimation is valid if we take $\gamma_1=\kappa_5^{-1/(2\theta-1)}$.
\end{proof}

