An $r$-uniform hypergraph ($r$-graph) $G=(V,E)$ consists of a vertex set $V:=\{1,2,\dots,n\}$ and an edge set $E\subseteq V^{(r)}$, where $V^{(r)}$ denotes the collection of all subsets of $V$ of size $r$,
$m=|E|$ is the number of edges. For example the sunflower hypergraph in Figure \ref{sunflower} is a $4$-uniform hypergraph with $10$ vertices. The weight polynomial for $G$ is defined as $w(G,\xv):=\sum_{e\in E}\prod_{i\in e}x_i$, where legal weighting for $G$ satisfies $x_i\ge0$ for all $i\in V$ and $\sum_{i\in V}x_i=1$.
Let $\Delta:=\{\xv\in \Re^n_+:\one^T\xv=1\}$ be the legal weighting set that is a simplex. Here $\one$ is the all one vector. The Lagrangian of an $r$-graph $G$ \cite{MS-65,Ta-02} is to maximize the weight polynomial $w(G,\xv)$ under the simplex constraint
\begin{equation}\label{Lagr}
  \lambda(G) := \max\left\{w(G,\xv)=\sum_{e\in E}\prod_{i\in e}x_i~:~\one^T\xv=1,~\xv\in\Re^n_+\right\}.
\end{equation}

\begin{Def}[Symmetry tensor \cite{QL-book}]
  A tensor $$\mathcal{T}=(t_{i_1\ldots i_r})\in \Re^{[r,n]}, \qquad \text{for} \ i_j = 1,\ldots, n, j = 1,\ldots,r$$ is an $r$th order $n$ dimensional symmetric tensor if the value of $t_{i_1\ldots i_k}$ is invariable under any permutation of its indices.
\end{Def}

\begin{Def}[Adjacency tensor \cite{CoD-12}]
  Let $G=(V,E)$ be an $r$-graph with $n$ vertices. The adjacency tensor of $G$ is an $r$th order $n$-dimensional symmetric tensor $\At=[a_{i_1 \cdots i_r}]$, of which elements are
  \begin{equation*}
    a_{i_1 \cdots i_r}=\left\{\begin{aligned}
      &\frac{1}{(r-1)!} && \quad\text{ if }\{i_1,\ldots,i_r\}\in E, \\
      &0                && \quad\text{ otherwise. }
    \end{aligned}\right.
  \end{equation*}
\end{Def}

\begin{Lem}
  Let $G$ be an $r$-graph with  $n$ vertices. Its weight polynomial $w(G,\xv)$ could be rewritten as
  \begin{equation*}
    w(G,\xv) = \frac{1}{r}\At\xv^r,
  \end{equation*}
  where $\At\xv^r := \sum_{i_1=1}^n\cdots\sum_{i_r=1}^n a_{i_1\cdots i_r}x_{i_1}\cdots x_{i_r}$.
\end{Lem}

\begin{proof}
  By direct calculations, it yields that
  \begin{eqnarray}
  \frac{1}{r}\At\xv^r &=& \frac{1}{r}\sum_{i_1=1}^n\cdots\sum_{i_r=1}^n a_{i_1\cdots i_r}x_{i_1}\cdots x_{i_r} \nonumber\\
    &=& \frac{1}{r}\sum_{{\{i_1,\dots,i_r\}\in E}\atop i_1<\dots<i_r} \frac{1}{(r-1)!} r! x_{i_1}\cdots x_{i_r} \nonumber\\
    &=& \sum_{e\in E}\prod_{i\in e}x_i = w(G,\xv). \label{aaabbb}
  \end{eqnarray}
  The proof is completed.
\end{proof}

\begin{proof}
  By direct calculations, it yields that
  \begin{eqnarray}
  \frac{1}{r}\At\xv^r &=& \frac{1}{r}\sum_{i_1=1}^n\cdots\sum_{i_r=1}^n a_{i_1\cdots i_r}x_{i_1}\cdots x_{i_r} \nonumber\\
    &=& \frac{1}{r}\sum_{{\{i_1,\dots,i_r\}\in E}\atop i_1<\dots<i_r} \frac{1}{(r-1)!} r! x_{i_1}\cdots x_{i_r} \nonumber\\
    &=& \sum_{e\in E}\prod_{i\in e}x_i = w(G,\xv). \label{aaabbb}
  \end{eqnarray}
  The proof is completed.
\end{proof}

Hence, to compute the Lagrangian of an $r$-graph $G$, we will solve the following optimization problem
\begin{equation}\label{OPM}
\lambda(G)=\left\{\begin{aligned}
  & \max && f(\xv)=\frac{1}{r}\At\xv^r \\
  & ~\mathrm{s.t.}&& \xv\in\Delta,
\end{aligned}\right.
\end{equation}

which is equivalent to \eqref{Lagr}. Since the adjacency tensor $\At$ of $G$ is symmetric, it holds \cite{QL-book,CDQY18} that $\nabla f(\xv)=\At\xv^{r-1}$, where elements of the vector $\At\xv^{r-1}$ are
\begin{equation*}
  (\At\xv^{r-1})_j=\sum_{i_2=1}^n\cdots\sum_{i_r=1}^n a_{ji_2\cdots i_r}x_{i_2}\cdots x_{i_r} \qquad
  \forall~j=1,\dots,n.
\end{equation*}

It is easy to see that the feasible region $\Delta$ is a closed convex set. The Euclidean projection
\begin{equation*}
  \pi_{\Delta}(\av) := \arg\min\limits_{\xv\in\Delta} \|\xv-\av\|
\end{equation*}
exists and is unique for any vector $\av\in\Re^n$. Algorithm \ref{Alg:Proj} provides an $\mathcal{O}(n\log n)$ approach for computing the Euclidean projection onto $\Delta$ \cite{WC'13,CY'11}.

\begin{algorithm}[t]
\caption{A gradient projection algorithm (GPA).}\label{Alg:pGrad}
\begin{algorithmic}[1]
  \STATE Choose $0<\underline{\alpha}\le\alpha_0\le\overline{\alpha}$, $\beta\in(0,1)$, $\eta\in(0,1/2]$, and $\xv_0\in\Delta$. Set $c\gets0$.
  \WHILE{the sequence of iterates does not converge}
    \STATE Set $\gv_c = \pi_{\Delta}(\xv_c + \alpha_c\nabla f(\xv_c))-\xv_c$.
    \STATE Find the smallest nonnegative integer $j$ such that
      \begin{equation}\label{LineSch}
        f(\xv_c+\beta^j\gv_c)-f(\xv_c) \ge \eta\beta^j \gv_c^T \nabla f(\xv_c).
      \end{equation}
    \STATE Set $\rho_c=\beta^j$ and $\xv_{c+1}=\xv_c+\rho_c\gv_c$.
    \STATE Choose $\alpha_{c+1}\in[\underline{\alpha},\overline{\alpha}]$ and set $c\gets c+1$.
  \ENDWHILE
\end{algorithmic}
\end{algorithm}

Now, we analyze the convergence of the proposed GPA. Part of our analysis on basic theory is similar to \cite{Ber-book,HZ'06} and we present here for the purpose of completion. First, we call $\xv_*\in\Delta$ a critical point of \eqref{OPM} if
\begin{equation*}
  \pi_{\Delta}(\xv_*+\nabla f(\xv_*))=\xv_*.
\end{equation*}

Because $f(\xv)=\frac{1}{r}\At\xv^r$ is a polynomial and the simplex $\Delta$ is compact, the Hessian $\nabla^2 f(\xv)$ is bounded, i.e., there exists a constant $M\ge1$ such that
\begin{equation*}
  \|\nabla^2 f(\xv)\| \le M  \qquad \forall \xv\in\Delta.
\end{equation*}

\begin{Thm}[{\L}ojasiewicz property]\label{Thm:5-1}
  Suppose that $\xv_*$ is a critical point of \eqref{OPM}, i.e., $\gv^1(\xv_*)=0$. Then, there exist a neighborhood of $\xv_*$ denoted as $\mathds{U}(\xv_*)$, an exponent $\theta\in[1/2,1)$, and a positive constant $C$ such that the following inequality
  \begin{equation*}
    \|\gv^1(\xv)\| \ge C|f(\xv)-f(\xv_*)|^{\theta}
  \end{equation*}
  holds for all $\xv\in \mathds{U}(\xv_*) \cap\Delta$.
\end{Thm}

\begin{Lem}\label{Lem:4-2}
  There exists a constant $\kappa_1>0$ such that for any $\rho_c$ generated by Algorithm \ref{Alg:pGrad}
  \begin{equation*}
    \rho_c\ge \kappa_1.
  \end{equation*}

\end{Lem}

\begin{proof}
  We will prove that the inequality \eqref{LineSch} is valid
