  which means
  \begin{equation*}
    \xi_c \le \left(\kappa_5c+\xi_0^{-(2\theta-1)}\right)^{-1/(2\theta-1)}
      \le (\kappa_5c)^{-1/(2\theta-1)}.
  \end{equation*}
The second estimation is valid if we take $\gamma_1=\kappa_5^{-1/(2\theta-1)}$.
\end{proof}

\begin{algorithm}[t]
\caption{Euclidean projection $\pi_{\Delta}(\av)$.}\label{Alg:Proj}
\begin{algorithmic}[1]
  \STATE Sort the input vector $\av\in\Re^n$ into an auxiliary vector $\bv$ such that $b_1\ge b_2\ge \dots\ge b_n$.
  \STATE Find the largest index $\ell=\max\{j: jb_j+1-\sum_{i=1}^j b_i>0, 1\le j\le n\}$.
  \STATE Set $\lambda = (1-\sum_{i=1}^{\ell} b_i)/{\ell}$.
  \STATE Output $\xv$ with $x_i=\max\{a_i+\lambda,0\}$.
\end{algorithmic}
\end{algorithm}
